    'admin_fair-defaults.ai_disabled_help' => 'Les calculs FAIR assistés par IA nécessitent l\'activation d\'une plateforme IA (OpenWebUI ou LibreChat). <a href="admin.php?section=ai-integration">Configurez d\'abord les paramètres d\'intégration IA</a>.',
