    'admin_shadow-saas-grip.abort_failed_prefix' => 'Echec de l\'interruption de la synchronisation : ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'Interrompre la synchronisation Grip en cours ?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'Interrompre la synchronisation HERO en cours ?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security decouvre et surveille en continu les applications SaaS-of-Record dans l\'ensemble de votre environnement.
Cette integration :<br><br>
<strong>&bull; Reflete les donnees Grip :</strong> Extrait l\'inventaire complet SaaS / utilisateurs / alertes vers les tables <code>shadow_saas_grip_*</code>.<br>
<strong>&bull; Hydrate Shadow SaaS :</strong> Projette chaque application SaaS dans la liste Shadow SaaS existante, en normalisant l\'URL vers son domaine enregistrable afin que la correspondance des fournisseurs fonctionne de la meme maniere qu\'un import CSV.<br>
<strong>&bull; Suit le risque :</strong> Conserve le score de risque de Grip, le tag de sanction, le nombre de portees OAuth, la classification de profondeur IA, la prise en charge MFA / SAML, et les metadonnees du contact principal.<br>
<strong>&bull; Reste a jour :</strong> Se relance selon le calendrier cron configure ; les administrateurs peuvent aussi declencher une execution immediate en arriere-plan avec le bouton "Executer maintenant" ci-dessus.',
    'admin_shadow-saas-grip.about_grip_heading' => 'A propos de l\'integration Grip',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security decouvre les fournisseurs SaaS tiers et les problemes qui les affectent dans l\'ensemble de votre environnement.
Cette integration :<br><br>
<strong>&bull; Reflete les donnees HERO :</strong> Extrait les fournisseurs / problemes / utilisateurs par fournisseur vers les tables <code>shadow_saas_hero_*</code>.<br>
<strong>&bull; Hydrate Shadow SaaS :</strong> Projette chaque fournisseur dans la liste Shadow SaaS existante par domaine enregistrable, afin que la correspondance fonctionne de la meme maniere qu\'un import CSV.<br>
<strong>&bull; Suit le risque :</strong> Derive un score de risque de 1 a 5 a partir du pire probleme ouvert par fournisseur (la meme echelle 1-5 qu\'utilise Grip) et enregistre le statut du fournisseur et les aspects d\'engagement.<br>
<strong>&bull; Reste a jour :</strong> Se relance dans le cadre de la tache partagee de rehydratation planifiee ; les administrateurs peuvent aussi declencher une execution immediate avec le bouton "Executer maintenant" ci-dessous.',
    'admin_shadow-saas-grip.about_hero_heading' => 'A propos de l\'integration HERO',
    'admin_shadow-saas-grip.api_key_label' => 'Cle d\'API',
    'admin_shadow-saas-grip.api_reference_heading' => 'Reference de l\'API',
    'admin_shadow-saas-grip.api_token_help' => 'Envoye comme en-tete HTTP <code>access-token</code> a chaque requete. Laissez vide pour conserver le jeton existant.',
    'admin_shadow-saas-grip.api_token_label' => 'Jeton d\'API',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'L\'hote de l\'URL de l\'API n\'est pas autorise.',
    'admin_shadow-saas-grip.api_url_invalid' => 'L\'URL de l\'API doit etre une URL http(s) valide.',
    'admin_shadow-saas-grip.api_url_label' => 'URL de l\'API',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' applications avec utilisateurs',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Contient actuellement ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>En direct</strong> appelle l\'API Grip pour chaque page (toujours a jour, plus lourd pour l\'API). <strong>Local (Hydrate/mis en cache)</strong> sert les tables <code>shadow_saas_grip_*</code> hydratees dans la base de donnees - plus leger pour l\'API - et un instantane par application manquant est recupere une fois depuis l\'API, puis mis en cache. En mode Local, chaque synchronisation <strong>rafraichit entierement</strong> les donnees : les tables miroir Grip sont videes et re-hydratees depuis l\'API.',
    'admin_shadow-saas-grip.data_source_label' => 'Source de donnees',
    'admin_shadow-saas-grip.data_source_live' => 'En direct - interroger l\'API Grip a chaque affichage',
    'admin_shadow-saas-grip.data_source_local' => 'Local (Hydrate/mis en cache) - servir depuis la base de donnees',
    'admin_shadow-saas-grip.download_postman_json' => 'Telecharger Postman (JSON)',
    'admin_shadow-saas-grip.download_swagger_yaml' => 'Telecharger Swagger (YAML)',
    'admin_shadow-saas-grip.enable_grip' => 'Activer l\'integration Grip Security',
    'admin_shadow-saas-grip.enable_hero' => 'Activer l\'integration HERO Security',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Activer la rehydratation planifiee',
    'admin_shadow-saas-grip.enable_zscaler' => 'Activer le blocage par categorie d\'URL Zscaler lors d\'un refus',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Saisissez la cle d\'API administrateur',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'Echec du vidage de ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Transferer les informations de violation Grip vers les Alertes de violation&nbsp;/&nbsp;cyber',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'Toutes les donnees Grip effacees : ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' table(s) miroir videe(s), ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' ligne(s) Shadow SaaS supprimee(s), et ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' fiche(s) fournisseur nettoyee(s) de la telemetrie Grip enregistree.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Inventaire des points de terminaison pour l\'API publique Grip Security (base serveur <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, OpenAPI 3.1 auto-generee). La synchronisation FairTPRM consomme les points de terminaison de lecture (GET) marques <em>utilises par la synchronisation</em> ; l\'inventaire complet &mdash; y compris les groupes Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions et AI&nbsp;Agents &mdash; figure dans les telechargements OpenAPI et Postman ci-dessous. L\'extraction de domaine normalise les URL vers leur domaine enregistrable (par ex. <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'En-tete d\'authentification : <code>access-token: &lt;your-token&gt;</code>. La variable <code>accessToken</code> de la collection Postman est definie sur <code>REPLACE_ME</code> ; remplacez-la par le jeton de votre tenant avant d\'envoyer des requetes.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'URL Grip prefixee du tenant, ancree a <code>/public/saas</code> (par ex. <code>https://tenant.dep.grip.security/public/saas</code>). Les points de terminaison associes (<code>/public/users</code>, <code>/public/alerts</code>) sont derives de cet hote.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Serveur (URL de base du tenant)',
    'admin_shadow-saas-grip.grip_breach_help' => 'A chaque rehydratation planifiee (et via le bouton manuel <strong>Executer&nbsp;maintenant</strong> ci-dessous), les alertes Grip "Security Incident Detected" sont ecrites dans le systeme <a href="breach-alerts.php">Alertes de violation&nbsp;/&nbsp;cyber</a> (dedupliquees). Les violations concernant un fournisseur integre sont liees a ce fournisseur ; les violations concernant une application sans fournisseur integre sont tout de meme enregistrees et etiquetees <strong>Shadow&nbsp;SaaS</strong> avec le nombre d\'utilisateurs potentiellement impactes. Necessite Grip active (ci-dessus) <em>et</em> le parametre Alerte de violation&nbsp;/&nbsp;cyber sous <a href="admin.php?section=email">E-mail &amp; Alertes</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'Echec de la mise a jour de la configuration Grip : ',
    'admin_shadow-saas-grip.grip_config_updated' => 'Configuration Grip mise a jour avec succes.',
