    'admin_shadow-saas-grip.hero_api_reference_intro' => 'Inventaire des points de terminaison pour l\'API publique HERO utilisee par cette integration. L\'authentification est OAuth 2.0 client-credentials &rarr; jeton Bearer ; les points de terminaison de liste utilisent la pagination par curseur (<code>next_cursor</code> &rarr; <code>cursor</code>).',
    'admin_shadow-saas-grip.hero_auth_help' => 'Authentification : <code>Authorization: Bearer &lt;token&gt;</code> sur tous les points de terminaison de donnees. Les jetons expirent apres ~1 heure.',
    'admin_shadow-saas-grip.hero_base_url_help' => 'Base de l\'API publique HERO, par ex. <code>https://api.herosecurity.ai/stable</code>. Les points de terminaison (<code>/v1/vendors</code>, <code>/v1/issues</code>) sont derives de cet hote.',
