    'admin_shadow-saas-grip.hero_mirror_vendors_desc' => 'Une ligne par fournisseur HERO (statut, aspects, score de risque derive 1-5, charge utile complete).',
    'admin_shadow-saas-grip.hero_pacing_help' => 'HERO limite le debit des appels API (~60 requetes par minute, a l\'echelle du compte). Ces parametres controlent le cadencement de la synchronisation des utilisateurs par fournisseur.',
