    'admin_shadow-saas-grip.hero_test_failed_prefix' => 'Echec du test HERO : ',
    'admin_shadow-saas-grip.hero_throttle_help' => 'Pause entre chaque requete d\'utilisateurs de fournisseur. ~1100&nbsp;ms maintient une synchronisation complete juste sous la limite ~60/min de HERO. Plus bas est plus rapide mais declenche des temporisations de limitation de debit (429).',
    'admin_shadow-saas-grip.hero_throttle_label' => 'Delai entre les appels de fournisseurs (ms)',
