    'admin_shadow-saas-grip.providers_mutually_exclusive_help' => 'Grip et Hero sont mutuellement exclusifs - activer l\'un desactive l\'autre. Le fournisseur actif (&#9679;) alimente le blocage Zscaler partage et la rehydratation planifiee ci-dessous.',
