    'admin_shadow-saas-grip.sched_enable_help' => 'Lorsqu\'elle est activee, la tache est installee dans le crontab du systeme et s\'execute selon le calendrier ci-dessous. Un fichier de verrouillage empeche les executions simultanees. L\'execution utilise le fournisseur active, quel qu\'il soit.',
    'admin_shadow-saas-grip.sched_rehydration_heading' => 'Rehydratation planifiee',
    'admin_shadow-saas-grip.sched_rehydration_intro' => 'Execute le fournisseur Shadow SaaS active (Grip ou Hero) selon un calendrier, en rafraichissant les tables miroir et la liste Shadow SaaS. Le calendrier ci-dessous est installe automatiquement dans le crontab du systeme &mdash; aucune modification manuelle du crontab, et il survit aux redemarrages du conteneur.',
    'admin_shadow-saas-grip.schedule_cron_label' => 'Calendrier (expression cron)',
