    'admin_shadow-saas-grip.truncate_all_confirm' => 'Vider TOUTES les donnees Grip locales ? Cela supprime definitivement chaque ligne miroir Grip (applications, utilisateurs, alertes, utilisateurs par application), retire toutes les lignes Shadow SaaS projetees par Grip, et efface la telemetrie Grip curatee enregistree sur les fiches fournisseurs (l\'onglet \'SaaS Data\' du fournisseur). La prochaine synchronisation la re-hydrate depuis l\'API Grip. Cette action est irreversible.',
