    'admin_shadow-saas-grip.zscaler_api_url_help' => 'Base OneAPI : <code>https://api.zsapi.net</code> (universelle). Par-cloud (ancien) : <code>https://zsapi.&lt;cloud&gt;.net</code> (par ex. <code>zscaler</code>, <code>zscalerone</code>, <code>zscalertwo</code>, <code>zscalerthree</code>, <code>zscloud</code>).',
    'admin_shadow-saas-grip.zscaler_config_update_failed_prefix' => 'Echec de la mise a jour de la configuration Zscaler : ',
