    'admin_shadow-saas-grip.zscaler_enable_help' => 'Lorsqu\'il est active, le bouton Refuser dans Shadow SaaS pousse le domaine du fournisseur dans la categorie d\'URL configuree. Lorsqu\'il est desactive, Refuser met uniquement a jour l\'etat local.',
    'admin_shadow-saas-grip.zscaler_intro' => 'Lorsqu\'un fournisseur est refuse depuis la liste Shadow SaaS, le domaine du fournisseur est ajoute a la categorie d\'URL ci-dessous dans Zscaler ZIA (en utilisant <code>action=ADD_TO_LIST</code>), puis active. Partage par les deux fournisseurs.',
    'admin_shadow-saas-grip.zscaler_password_help' => 'Le <code>client_secret</code> affiche <strong>une seule fois</strong> lors de la creation de l\'API Client. Stocke chiffre. Laissez vide pour conserver la valeur existante.',
