    'admin_shadow-saas-grip.zscaler_username_placeholder' => 'UUID depuis ZIdentity → Integration → API Clients',
    'admin_shadow-saas-grip.zscaler_vanity_help' => 'Hote du point de terminaison de jeton OAuth du tenant ZIdentity - l\'URL du jeton est <code>https://&lt;vanity&gt;/oauth2/v1/token</code>. Trouvez-le dans l\'URL d\'administration ZIdentity (la partie avant <code>.zslogin.net</code>).',
    'admin_shadow-saas-grip.zscaler_vanity_label' => 'Domaine personnalise ZIdentity',
    'admin_shodan-srs.about_body' => 'Shodan est une plateforme de renseignement sur internet qui analyse et indexe chaque appareil connecte a internet qu\'elle peut trouver. L\'integration permet :<br><br><strong>• Analyse des ports :</strong> Identifier les ports ouverts sur l\'infrastructure des fournisseurs, y compris les services a haut risque (FTP, Telnet, RDP, SMB)<br><strong>• Detection des vulnerabilites :</strong> Decouvrir les CVE connues associees aux adresses IP et services des fournisseurs<br><strong>• Identification des services :</strong> Cataloguer les services en cours d\'execution, les versions de logiciels et les configurations de serveur<br><strong>• Scoring de securite :</strong> Generer un score de securite de 0 a 100 base sur la surface d\'attaque exposee',
    'admin_shodan-srs.about_heading' => 'A propos de Shodan',
    'admin_shodan-srs.about_learn_more' => 'En savoir plus sur Shodan →',
    'admin_shodan-srs.about_note_body' => 'Les scores Shodan sont complementaires aux scores UpGuard. UpGuard se concentre sur la posture de securite globale (echelle 0-950), tandis que Shodan se concentre sur l\'infrastructure exposee (echelle 0-100). Les deux peuvent etre actives simultanement pour des evaluations completes des fournisseurs.',
    'admin_shodan-srs.about_note_label' => 'Remarque :',
    'admin_shodan-srs.across' => 'reparties sur',
    'admin_shodan-srs.active_waiver_singular' => 'derogation active',
    'admin_shodan-srs.active_waivers_plural' => 'derogations actives',
    'admin_shodan-srs.api_key_help' => 'Cle API de votre <a href="https://account.shodan.io" target="_blank">compte Shodan</a>. Laissez vide pour conserver la cle existante.',
    'admin_shodan-srs.api_key_label' => 'Cle API Shodan',
    'admin_shodan-srs.api_key_placeholder' => 'Saisissez la cle API',
    'admin_shodan-srs.banner_max_age_help' => 'Ignorer les donnees de banniere Shodan plus anciennes que ce nombre de jours. Shodan conserve des donnees historiques pour des ports qui peuvent desormais etre filtres/fermes. Definissez a 0 pour desactiver le filtrage par fraicheur. Par defaut : 7 jours.',
    'admin_shodan-srs.banner_max_age_label' => 'Age maximal de la banniere (jours)',
    'admin_shodan-srs.connection_test_error' => 'Erreur du test de connexion Shodan. Consultez le journal des erreurs pour plus de details.',
