    'admin_shodan-srs.min_cve_year_help_prefix' => 'Exclure des resultats d\'analyse les CVE publiees avant cette annee. Par defaut : 0 = automatique (annee en cours moins 5, actuellement ',
    'admin_shodan-srs.min_cve_year_help_suffix' => '). La detection de Shodan basee sur les bannieres fait souvent correspondre des CVE tres anciennes a des chaines de version de logiciel, produisant des faux positifs. Definissez une annee specifique pour remplacer, ou laissez a 0 pour utiliser la fenetre glissante de 5 ans.',
