    'admin_shodan-srs.on_demand_help' => 'Lorsque cette option est activee, Shodan demandera une analyse a la demande pour toute adresse IP pour laquelle il n\'a pas de donnees existantes pendant le scoring. Cela garantit la couverture des domaines que Shodan n\'a pas analyses auparavant, mais consomme des credits d\'analyse (1 credit par IP) et ajoute jusqu\'a 3 minutes de temps d\'attente par requete de scoring pendant que Shodan traite l\'analyse. Recommande pour les fournisseurs pour lesquels Shodan ne renvoie aucun signal de securite.',
    'admin_shodan-srs.on_demand_label' => 'Activer l\'analyse a la demande',
    'admin_shodan-srs.randomize_subdomains_help' => 'Lorsque cette option est activee, les sous-domaines sont choisis de maniere aleatoire plutot qu\'alphabetiquement. Offre une couverture plus large sur les analyses repetees.',
