    'admin_shodan-srs.rescan_cooldown_help' => 'Supprimer les requetes de nouvelle analyse en double pour les IP deja re-analysees dans cette fenetre. Chaque nouvelle analyse debite des credits d\'analyse Shodan, ce qui evite les frais repetes accidentels dus a des double-clics ou a des nouvelles analyses manuelles consecutives. Definissez a 0 pour desactiver le delai (chaque clic re-analyse chaque IP). Par defaut : 24 heures.',
