    'admin_shodan-srs.weights_intro' => 'Ajustez la contribution de chaque categorie de securite au score final. Les ponderations sont relatives - elles n\'ont pas besoin de totaliser exactement 100, mais seront normalisees proportionnellement.',
    'admin_shodan-srs.weights_warning' => 'Les ponderations ne totalisent pas 100 % - elles seront normalisees proportionnellement lors du calcul du score final.',
