    'admin_shodan-srs.word_waivers' => 'derogations',
    'admin_srs.about_custom_body' => 'Le scoring personnalisé vous permet de saisir manuellement les scores de sécurité des fournisseurs à l\'aide d\'outils d\'évaluation ou de services de notation externes.<br><br><strong>Plage de scores :</strong> 1-100 (échelle en pourcentage)<br><strong>Notation :</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>Lorsque plusieurs sources de scoring existent (UpGuard, Shodan, personnalisé), un score moyen combiné est calculé et affiché dans toute l\'application. Cela offre une vue unifiée de la posture de sécurité de chaque fournisseur à partir de toutes les sources disponibles.',
    'admin_srs.about_custom_heading' => 'À propos du scoring personnalisé',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk fournit des notations de sécurité automatisées et une surveillance continue des fournisseurs tiers. L\'intégration permet :<br><br><strong>• Scoring de sécurité automatisé :</strong> Obtenez des notations de sécurité instantanées (0-950) pour les fournisseurs en fonction de leur posture de sécurité externe<br><strong>• Identification des risques :</strong> Identifiez automatiquement les risques de sécurité de gravité élevée, moyenne et faible<br><strong>• Analyse des tendances :</strong> Suivez les scores de sécurité des fournisseurs au fil du temps pour identifier les améliorations ou les dégradations<br><strong>• Surveillance par niveau :</strong> Configurez la fréquence de réévaluation en fonction de la criticité du fournisseur',
    'admin_srs.about_upguard_heading' => 'À propos d\'UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'En savoir plus sur UpGuard CyberRisk &rarr;',
    'admin_srs.api_key_help' => 'Clé API de la console UpGuard CyberRisk. Laissez vide pour conserver la clé existante.',
