    'admin_srs.cron_job_required' => 'Tâche cron requise',
    'admin_srs.cron_lock_files_note' => 'Utilise des fichiers de verrouillage pour empêcher les exécutions simultanées. Consultez le <span data-action="openCronInfoModal" style="color: var(--theme-header-color, #2563eb); cursor: pointer; text-decoration: underline;">Guide de configuration de Cron</span> pour plus de détails.',
    'admin_srs.cron_modal_heading' => 'Configuration de la tâche cron pour la réévaluation SRS',
    'admin_srs.cron_note_body' => 'L\'historique d\'exécution est enregistré dans la base de données. Consultez Admin &gt; SRS pour les exécutions passées et les éventuelles erreurs.',
    'admin_srs.cron_ondemand_desc' => 'Traite les demandes de réévaluation manuelles mises en file d\'attente depuis la page des détails du fournisseur. <strong>Requis</strong> lorsque « Utiliser Cron pour la réévaluation » est activé sur l\'une ou l\'autre des intégrations :',
    'admin_srs.cron_ondemand_heading' => '2. File d\'attente de réévaluation à la demande <span style="background: #dbeafe; color: #1e40af; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; vertical-align: middle;">Requis pour « Utiliser Cron »</span>',
    'admin_srs.cron_ondemand_note' => 'Exécutée chaque minute. Utilise des fichiers de verrouillage pour empêcher les exécutions simultanées. Ne traite qu\'un fournisseur à la fois pour éviter les limites de débit de l\'API. Si aucune réévaluation n\'est en attente, la tâche se termine immédiatement.',
    'admin_srs.cron_prereq_enabled' => 'Assurez-vous qu\'au moins une intégration SRS est activée avec une clé API valide',
    'admin_srs.cron_prereq_log_dir' => 'Créez le répertoire de journaux si nécessaire : <code style="background: #f8f9fa; padding: 2px 6px; border-radius: 3px;">sudo mkdir -p /var/log</code>',
    'admin_srs.cron_prereq_php_cli' => 'Vérifiez que PHP CLI est installé : <code style="background: #f8f9fa; padding: 2px 6px; border-radius: 3px;">php -v</code>',
